            .torrentRemoveConfirm: "apagar arquivos?", .torrentRemoveKeep: "manter arquivos", .torrentRemoveDelete: "apagar com arquivos", .torrentRemoveTorrent: "apagar torrent", .torrentRemoveMagnet: "apagar magnet", .torrentFilesRemoved: "arquivos removidos · retomar para baixar de novo",
