            .torrentPeers: "节点", .torrentEta: "剩余", .torrentRatio: "分享率", .torrentReveal: "在访达中显示",
            .torrentRemoveConfirm: "同时删除文件？", .torrentRemoveKeep: "保留文件", .torrentRemoveDelete: "连同文件删除", .torrentRemoveTorrent: "删除种子", .torrentRemoveMagnet: "删除 magnet", .torrentFilesRemoved: "文件已删除 · 恢复以重新下载",
            .torrentFolderLabel: "下载文件夹", .torrentStopRatio: "分享率 1.0 时停止",
