            .archivePacked: "đã nén", .archiveGettingHelper: "đang tải trình hỗ trợ", .archiveHelperFailed: "không dùng được trình hỗ trợ",
            .archiveEmpty: "bên trong trống", .archiveFailed: "không được",
            .docArchiveFull: "nén và giải nén bằng kéo thả, kết quả luôn nằm NGAY CẠNH bản gốc — không cửa sổ, không trình hướng dẫn, không phải bới thư mục tải về.\n\n• {sym:archivebox} giải nén — thả kho nén lên thẻ và nó bung ra ngay tại chỗ đang nằm. bên trong chỉ có một mục thì ra đúng mục đó; nhiều mục thì nằm gọn trong một thư mục mang tên kho nén, nên không có gì vương vãi trên màn hình nền. tên đã tồn tại không bao giờ bị ghi đè — tên mới được đánh số, giống cách Finder làm.\n\n• nén — thả tệp hoặc thư mục vào, một kho nén sẽ xuất hiện bên cạnh chúng. các chip định dạng chọn thứ cần tạo: zip, tar.gz hoặc 7z.\n\n• mở được ngay — zip, tar, tar.gz, tar.bz2, tar.xz và gz chạy bằng công cụ macOS đã có sẵn.\n\n• rar và 7z — cần trình hỗ trợ 7-Zip (~6 MB): tải về lần đầu bạn thả loại kho đó và chỉ cài sau khi chữ ký khớp. Hop giải nén rar nhưng không bao giờ tạo: định dạng này là độc quyền và không có trình nén tự do nào viết được.\n\n• kho nén tạo ra rất sạch — không có rác __MACOSX, nên mở trên Windows hay Linux đều đúng.",
            .convCanDocuments: "tài liệu", .convModeLabel: "chế độ", .convModeCompress: "nén",
            .convDocNote: "bố cục word như chia cột và chú thích chân trang sẽ được đơn giản hoá; pdf → md lấy văn bản kèm tiêu đề, không phải bố cục",
            .docConverterDocs: "tài liệu — markdown, tệp word và pdf chuyển qua lại lẫn nhau, trong cùng một cửa sổ và cùng một mẻ.\n\n• md → pdf — do chính Hop dàn trang: tiêu đề, danh sách, trích dẫn, khối mã và liên kết trên trang A4 với lề tử tế. bộ máy markdown là của chúng tôi, nên kết quả trông có chủ ý chứ không như bản in từ trình duyệt.\n\n• word (.docx, .doc, .rtf) → pdf hoặc md — văn bản, tiêu đề, nhấn mạnh, danh sách, bảng đơn giản và hình ảnh đều theo sang. cột, chú thích chân trang và đầu trang thì không: đó là bố cục, và bản chuyển đổi nói thẳng điều đó.\n\n• pdf → md — chuyển nhóm pdf sang md. pdf lưu bố cục chứ không lưu cấu trúc, nên đây là TRÍCH XUẤT văn bản kèm đoán tiêu đề: tài liệu thiên về chữ ra rất ổn, còn trang tạp chí thì thành văn xuôi. trang quét không có lớp văn bản được đọc bằng Vision, đúng bộ nhận dạng của mô-đun văn bản màn hình.\n\n• md → docx — khi tài liệu phải đến dưới dạng mà word mở được.\n\n• tất cả đều chạy trong máy và ngoại tuyến: không dịch vụ chuyển đổi, không kèm bộ ứng dụng văn phòng, không phải tải gì thêm.",
            .keylockLabel: "bàn phím", .keylockStart: "khoá", .keylockHint: "để lau — chuột mở khoá",
            .keylockSecondsUnit: "gi", .keylockTitle: "bàn phím đã khoá",
            .keylockBody: "cứ lau đi, các phím không làm gì cả.\nmở khoá bằng chuột, hoặc chờ hết giờ.",
            .keylockDone: "xong",
            .docKeylockFull: "chế độ lau chùi: một nút bấm và cả bàn phím ngừng phản hồi, để bạn lau mà không phải tắt máy hay gập màn hình.\n\n• {sym:keyboard} chuyện gì xảy ra — một tấm che toàn màn hình hiện ra, mọi lần nhấn, nhả và phím bổ trợ đều bị nuốt, kể cả hàng độ sáng, âm lượng và điều khiển nhạc. không có gì được ghi lại: các sự kiện bị bỏ đi chứ không được đọc.\n\n• thoát ra thế nào — bằng chuột hoặc trackpad: nút xong trên tấm che. phím tắt lại đúng là thứ vừa bị tắt. bộ đếm (30 giây, 1 phút hoặc 5 phút) sẽ tự nhả ra như một lưới an toàn.\n\n• nút nguồn và Touch ID vẫn hoạt động — macOS giữ riêng chúng, và lấy đi cũng không đúng.\n\n• quyền trợ năng — cùng quyền mà trình quản lý cửa sổ dùng: chính nó quản việc chặn phím ở mức hệ thống. không có nó thì phím vẫn chạy, nên Hop hỏi trước khi hứa hẹn một khoá.",
            .featureToolsTitle: "công cụ màn hình",
            .featureToolsBody: "ống hút màu cho mọi màu trên màn hình, và đọc văn bản hay mã qr thẳng vào lịch sử clipboard. dành cho nhà thiết kế và lập trình viên, nên mặc định tắt.",
            .permTab: "quyền", .permGranted: "đã cấp", .permNotGranted: "chưa cấp",
            .permWhenUsed: "hỏi khi dùng", .permNetworkTitle: "mạng — antonshakirov.com",
            .permNetworkBody: "kiểm tra và tải bản cập nhật, cùng hai trình hỗ trợ tuỳ chọn: engine torrent và trình nén 7-Zip. đây là máy chủ duy nhất Hop tự liên hệ.",
            .permTorrentTitle: "mạng — lưu lượng torrent",
