            .torrentMakeDefault: "Hop standaard voor .torrent", .torrentReadFailed: "kon deze torrent niet lezen",
            .torrentAdd: "torrent toevoegen", .torrentRemove: "verwijderen", .torrentShowWhenEmpty: "kaart tonen indien leeg",
